package com.afs.guard;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;import org.json.*;
public final class OptimizationDeviceTest extends Instrumentation{
 int checks;void check(boolean ok,String s){checks++;if(!ok)throw new AssertionError(s);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Context c=getTargetContext();String[] names={DailyQuotaStore.SP,AppUsageQuota.SP,DayBoundary.SP,"afs_bg"};Map<String,Map<String,?>> backups=new HashMap<>();for(String n:names)backups.put(n,new HashMap<>(c.getSharedPreferences(n,0).getAll()));Bundle out=new Bundle();int code=-1;boolean permission=AppUsageQuota.permission(c);
 try{check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("sdk_gphone"),"emulator only");getUiAutomation().executeShellCommand("appops set com.afs.guard GET_USAGE_STATS allow").close();Thread.sleep(1200);
 c.getSharedPreferences(DayBoundary.SP,0).edit().clear().putInt("reset_hour",0).commit();long now=System.currentTimeMillis();String a="com.afs.optimization.a",b="com.afs.optimization.b";
 JSONObject g=new JSONObject().put("id","existing").put("name","existing").put("minutes",20).put("apps",new JSONArray().put(b));JSONObject config=new JSONObject().put("enabled",true).put("groups",new JSONArray().put(g));JSONObject usage=DailyQuotaData.fresh(now);usage.getJSONObject("targets").put(b,12345L);
 SharedPreferences q=c.getSharedPreferences(DailyQuotaStore.SP,0);q.edit().putString("config",config.toString()).putString("usage",usage.toString()).commit();
 check(DayBoundary.saveHour(c,13),"pending time saved");check(DayBoundary.hour(c)==0&&DayBoundary.selectedHour(c)==13,"active reset stays unchanged until next boundary");DailyQuotaStore.beforeScheduleChange(c);check(DailyQuotaStore.snapshot(c).used(g)==12345L,"changing reset keeps real persisted usage");long due=c.getSharedPreferences(DayBoundary.SP,0).getLong("pending_at",0);DayBoundary.saveHour(c,16);check(c.getSharedPreferences(DayBoundary.SP,0).getLong("pending_at",0)==due,"second edit retains due time");
 DayBoundary.saveHour(c,0);check(!c.getSharedPreferences(DayBoundary.SP,0).contains("pending_hour"),"return to active reset cancels pending change");DayBoundary.saveHour(c,13);c.getSharedPreferences(DayBoundary.SP,0).edit().putLong("pending_at",now-1).commit();check(DayBoundary.hour(c)==13&&!c.getSharedPreferences(DayBoundary.SP,0).contains("pending_hour"),"due reset activates and clears pending marker");
 c.getSharedPreferences(DayBoundary.SP,0).edit().clear().putInt("reset_hour",0).commit();q.edit().putString("usage",usage.toString()).commit();JSONObject old=new JSONObject().put(a,30).put(b,15);c.getSharedPreferences(AppUsageQuota.SP,0).edit().putString("limits",old.toString()).commit();check(DailyQuotaStore.migrateLegacy(c)==1,"only non-conflicting old quota migrates");check(!AppUsageQuota.config(c).has(a)&&AppUsageQuota.config(c).optInt(b)==15,"conflicting old quota survives cleanup");JSONObject backupUsage=new JSONObject(q.getString("usage_before_migration","{}"));check(backupUsage.getJSONObject("targets").optLong(b)==12345&&!backupUsage.getJSONObject("targets").has(a),"backup is the unmodified original ledger");check(DailyQuotaStore.snapshot(c).group(a).optInt("minutes")==30,"new quota retains original cap");check(DailyQuotaStore.migrateLegacy(c)==0&&AppUsageQuota.config(c).has(b),"retry preserves conflict rather than deleting it");
 c.getSharedPreferences("afs_bg",0).edit().putString("src","default").commit();
 android.graphics.Bitmap backdrop=Backdrop.build(c,1272,2800);check(backdrop!=null&&backdrop.getWidth()==318&&backdrop.getHeight()==700,"backdrop retains only quarter-size texture");check(backdrop.getAllocationByteCount()<=1272L*2800*4/16,"backdrop bitmap is at most one sixteenth of full-size allocation");backdrop.recycle();
 config.put("enabled",false);q.edit().putString("config",config.toString()).commit();
 android.graphics.drawable.Drawable icon=AppIcons.drawable(c,c.getPackageName());check(icon instanceof android.graphics.drawable.BitmapDrawable,"static app icon is stored as a display-sized bitmap");check(icon.getIntrinsicWidth()<=Math.ceil(64*c.getResources().getDisplayMetrics().density),"icon is bounded to the largest supported 64dp display size");AppIcons.trim();check(AppIcons.drawable(c,c.getPackageName())!=null,"trimmed icons reload without losing app icons");
 java.util.concurrent.CountDownLatch held=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1);
 Thread writer=new Thread(()->{synchronized(DailyQuotaStore.class){held.countDown();try{release.await(1500,java.util.concurrent.TimeUnit.MILLISECONDS);}catch(InterruptedException ignored){}}});writer.start();held.await();long[] readMs={0};
 try{runOnMainSync(()->{long before=SystemClock.elapsedRealtime();DailyQuotaStore.snapshot(c);readMs[0]=SystemClock.elapsedRealtime()-before;});}finally{release.countDown();writer.join(3000);}
 check(readMs[0]<200,"UI quota snapshot never waits for the background writer monitor");
 long primed=System.currentTimeMillis();AppUsageQuota.spans(c,primed,true);Thread.sleep(20);
 long[] elapsed={0};runOnMainSync(()->{long start=SystemClock.elapsedRealtime();AppUsageQuota.foregroundCached(c,System.currentTimeMillis());elapsed[0]=SystemClock.elapsedRealtime()-start;});java.lang.reflect.Field busy=AppUsageQuota.class.getDeclaredField("foregroundBusy");busy.setAccessible(true);for(int i=0;i<100&&((java.util.concurrent.atomic.AtomicBoolean)busy.get(null)).get();i++)Thread.sleep(20);
 java.lang.reflect.Field stamp=AppUsageQuota.class.getDeclaredField("cachedAt");stamp.setAccessible(true);check(stamp.getLong(null)==primed,"foreground sampler reuses fresh quota scan without a second system query");
 out.putLong("cached_ui_call_ms",elapsed[0]);check(elapsed[0]<200,"cold UI cache request returns without system usage scan");out.putString("stream","Optimization device: "+checks+" checks passed; cold cache call "+elapsed[0]+" ms\n");code=0;
 }catch(Throwable e){out.putString("stream",android.util.Log.getStackTraceString(e));}finally{for(String n:names){SharedPreferences.Editor e=c.getSharedPreferences(n,0).edit().clear();for(Map.Entry<String,?> v:backups.get(n).entrySet()){Object x=v.getValue();if(x instanceof String)e.putString(v.getKey(),(String)x);else if(x instanceof Integer)e.putInt(v.getKey(),(Integer)x);else if(x instanceof Long)e.putLong(v.getKey(),(Long)x);else if(x instanceof Boolean)e.putBoolean(v.getKey(),(Boolean)x);}e.commit();}if(!permission)try{getUiAutomation().executeShellCommand("appops set com.afs.guard GET_USAGE_STATS default").close();}catch(Exception ignored){}finish(code,out);}}
}
